+  DType* push_buf[kNumGPU];
+#pragma unroll
+  for (uint32_t i = 0; i < kNumGPU; ++i) {
+    push_buf[i] = static_cast<DType*>(
+        ptr_byte_offset(buffer[i], rank * buffer_bytes, epoch_offset));
